const aiResponse = $input.first().json.output;

/**
 * Limpieza completa de caracteres problemáticos
 */
function cleanText(text) {
    if (!text || typeof text !== 'string') return text;

    return text
        // 1. NORMALIZAR Unicode
        .normalize('NFC')

        // 2. ELIMINAR caracteres de control invisibles (U+0000 a U+001F excepto los que manejamos)
        .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '')

        // 3. ELIMINAR Zero-Width spaces y caracteres invisibles
        .replace(/[\u200B-\u200D\uFEFF]/g, '')  // Zero-width space, joiner, non-joiner
        .replace(/\u00A0/g, ' ')                 // Non-breaking space → espacio normal

        // 4. ELIMINAR comillas (dobles y simples)
        .replace(/"/g, '')                       // ❌ Comillas dobles mueren
        .replace(/'/g, '')                       // ❌ Comillas simples mueren
        .replace(/`/g, '')                       // ❌ Backticks mueren

        // 5. CONVERTIR saltos de línea a comas
        .replace(/\r\n/g, ', ')                  // Windows line breaks → coma
        .replace(/\n/g, ', ')                    // Unix line breaks → coma
        .replace(/\r/g, ', ')                    // Old Mac line breaks → coma

        // 6. CONVERTIR tabs a espacios
        .replace(/\t/g, ' ')

        // 7. NORMALIZAR espacios múltiples
        .replace(/ {5,}/g, '    ')               // 5+ espacios → 4 espacios (límite WhatsApp)
        .replace(/  +/g, ' ')                    // 2+ espacios → 1 espacio

        // 8. LIMPIAR comas múltiples
        .replace(/, , +/g, ', ')                 // ", , " → ", "
        .replace(/,{2,}/g, ',')                  // ",," → ","
        .replace(/, ,/g, ', ')                   // ", ," → ", "

        // 9. LIMPIAR espacios alrededor de comas
        .replace(/ , /g, ', ')                   // " , " → ", "
        .replace(/,  +/g, ', ')                  // ",  +" → ", "

        // 10. TRIM profundo
        .trim()
        .replace(/^, /, '')                      // Quitar coma al inicio
        .replace(/, $/, '');                     // Quitar coma al final
}

const jsonBlockMatch = aiResponse.match(/```json\s*([\s\S]*?)\s*```/);
const hasJson = jsonBlockMatch !== null;
let orderData = null;
let isPedidoConfirmado = false;

if (hasJson) {
    try {
        const jsonString = jsonBlockMatch[1].trim();
        orderData = JSON.parse(jsonString);

        if (orderData && 
            orderData.pedido_id && 
            orderData.ventana_id && 
            orderData.lista_compras && 
            orderData.direccion && 
            orderData.zona_domicilio &&
            orderData.valor_oferta &&
            orderData.nombre_completo &&
            orderData.ciudad) {

            isPedidoConfirmado = true;

            // Limpiar todos los campos de texto
            orderData.lista_compras = cleanText(orderData.lista_compras);
            orderData.direccion = cleanText(orderData.direccion);
            orderData.nombre_completo = cleanText(orderData.nombre_completo);
            orderData.ciudad = cleanText(orderData.ciudad);
            orderData.zona_domicilio = cleanText(orderData.zona_domicilio);

            // Solo trim en campos numéricos/IDs
            orderData.pedido_id = String(orderData.pedido_id).trim();
            orderData.ventana_id = String(orderData.ventana_id).trim();
            orderData.valor_oferta = String(orderData.valor_oferta).trim();
        }
    } catch (error) {
        console.log('Error parsing JSON:', error);
        orderData = null;
    }
}

let cleanResponse = aiResponse;
if (hasJson) {
    cleanResponse = aiResponse.replace(jsonBlockMatch[0], '').trim();
    cleanResponse = cleanResponse.replace(/\n\s*\n+/g, '\n\n').trim();
}

return [{
    output: cleanResponse,
    is_pedido_confirmado: isPedidoConfirmado,
    order_data: orderData
}];

